/** Перевод условий воззваний колдуна. */
export function prereqRu(t) {
  if (!t) return '';
  return String(t).replace(/(\d+)(st|nd|rd|th) level/g, '$1 ур.').replace(/eldritch blast cantrip/gi, 'заговор «Мистический заряд»')
    .replace(/Pact of the Tome feature/gi, 'договор гримуара').replace(/Pact of the Blade feature/gi, 'договор клинка').replace(/Pact of the Chain feature/gi, 'договор цепи');
}

/** Английский текст SRD из PDF: склеиваем строки обратно в абзацы, короткие строки без точки — подзаголовки. */
export function reflow(text) {
  const lines = String(text || '').split('\n');
  const out = [];
  let cur = '';
  const flush = () => { if (cur.trim()) out.push({ p: cur.trim() }); cur = ''; };
  for (let i = 0; i < lines.length; i++) {
    const ln = lines[i].trim();
    if (!ln) { flush(); continue; }
    const prevEnd = cur ? /[.:!?”)]$/.test(cur.trim()) : true;
    const next = lines[i + 1]?.trim() || '';
    const heading = prevEnd && ln.length < 42 && /^[A-Z]/.test(ln) && !/[.,;:]$/.test(ln) && /^[A-Z]/.test(next) && ln.split(' ').length <= 6;
    if (heading) { flush(); out.push({ h: ln }); continue; }
    if (!cur) cur = ln;
    else if (/[a-z]-$/.test(cur)) cur = cur + ln; // перенос «1st-\nlevel»
    else cur += ` ${ln}`;
  }
  flush();
  return out;
}

